# The pattern: NO COLLISIONS means use BOTH, any collision means LEFT ONLY

def check_collision(left_row, right_row):
    """Returns True if any position has both left and right non-zero"""
    left_set = set(i for i, v in enumerate(left_row) if v != 0)
    right_set = set(i for i, v in enumerate(right_row) if v != 0)
    return len(left_set & right_set) > 0

def predict_output_new(left_row, right_row):
    """New hypothesis: No collision? Use both. Collision? Use left-only."""
    if check_collision(left_row, right_row):
